def kth_largest(nums: list[int], k: int) -> int:
    """
    Find the k-th largest element in an unsorted list using the Introselect algorithm.
    This algorithm is a hybrid of Quickselect and Heap Select strategies, with an average time complexity of O(n) and a worst-case time complexity of O(n log n).
    """
    if k < 1 or k > len(nums):
        raise ValueError("k is out of bounds of the list.")

    def introselect(left: int, right: int, k_smallest: int, depth_limit: int) -> int:
        if left == right:
            return nums[left]

        if depth_limit == 0:  # Switch to a sorting method
            return sorted(nums[left:right + 1])[k_smallest - left]

        pivot_index = random.randint(left, right)
        pivot_index = partition(left, right, pivot_index)

        if k_smallest == pivot_index:
            return nums[k_smallest]
        elif k_smallest < pivot_index:
            return introselect(left, pivot_index - 1, k_smallest, depth_limit - 1)
        else:
            return introselect(pivot_index + 1, right, k_smallest, depth_limit - 1)

    def partition(left: int, right: int, pivot_index: int) -> int:
        pivot_value = nums[pivot_index]
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left

        for i in range(left, right):
            if nums[i] > pivot_value:  # We want k-th largest
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1

        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    depth_limit = 2 * (right - left + 1).bit_length()  # Limit depth for hybrid method
    return introselect(0, len(nums) - 1, k - 1, depth_limit)

